INSERT INTO Products (id, name, description, price, stock_quantity, category_id, supplier_id) VALUES
    (1, 'Nova 55-inch 4K Smart TV', '55-inch 4K UHD television with HDR support and built-in streaming apps.', 978.90, 166, 1, 2),
    (2, 'Vireo Fitness Tracker', 'Lightweight activity tracker for steps, sleep and heart rate. Firmware updates via the companion app.', 72.99, 110, 1, 38),
    (3, 'Lumo Action Camera', 'Rugged 4K action camera with electronic image stabilisation. Supports fast charging.', 368.00, 154, 1, 38),
    (4, 'Vireo Over-Ear Headphones', 'Comfortable over-ear headphones with active noise cancellation.', 140.00, 116, 1, 37),
    (5, 'Kaiku Power Bank 20000 mAh', 'High-capacity power bank with USB-C fast charging. Available in black and white.', 35.95, 35, 1, 1),
