UPDATE Orders
SET order_date = order_date + INTERVAL DATEDIFF(NOW(), '2026-10-19') DAY,
    delivery_date = delivery_date + INTERVAL DATEDIFF(NOW(), '2026-10-19') DAY$$

UPDATE OrderLog l
JOIN Orders o ON o.id = l.order_id
SET l.placed_at = o.order_date$$
